def solution(messages, budget):
    # Brute force: try the longest suffix first and shrink it until it fits.
    # Re-summing every suffix makes this O(n^2).
    head = []
    if messages and messages[0][0] == 'system':
        head = [messages[0]]
        budget -= len(messages[0][1].split())
        messages = messages[1:]
    for k in range(len(messages), -1, -1):
        suffix = messages[len(messages) - k:]
        if sum(len(m[1].split()) for m in suffix) <= budget:
            return head + suffix
    return head
